INSERT INTO T_COMN_MENU_COLUMN_LINK (COLUMN_DEFINITION_ID,MENU_ID,COLUMN_NAME_JA,COLUMN_NAME_EN,COLUMN_NAME_REST,COL_GROUP_ID,COLUMN_CLASS,COLUMN_DISP_SEQ,REF_TABLE_NAME,REF_PKEY_NAME,REF_COL_NAME,REF_SORT_CONDITIONS,REF_MULTI_LANG,REFERENCE_ITEM,SENSITIVE_COL_NAME,FILE_UPLOAD_PLACE,BUTTON_ACTION,COL_NAME,SAVE_TYPE,AUTO_INPUT,INPUT_ITEM,VIEW_ITEM,UNIQUE_ITEM,REQUIRED_ITEM,AUTOREG_HIDE_ITEM,AUTOREG_ONLY_ITEM,INITIAL_VALUE,VALIDATE_OPTION,VALIDATE_REG_EXP,BEFORE_VALIDATE_REGISTER,AFTER_VALIDATE_REGISTER,DESCRIPTION_JA,DESCRIPTION_EN,NOTE,DISUSE_FLAG,LAST_UPDATE_TIMESTAMP,LAST_UPDATE_USER) VALUES('8010303','80103','Project名','Project name','tf_project_name',NULL,'1',30,NULL,NULL,NULL,NULL,'0',NULL,NULL,NULL,NULL,'PROJECT_NAME',NULL,'0','1','1','0','0','1','0',NULL,'{"min_length": 1, "max_length": 40}','^[a-zA-Z0-9_ -]+$',NULL,NULL,'Projectの名前。半角英数字と利用可能な記号(_ -)で入力。空白の場合は「Default Project」が使用されます。[最大長]40バイト','Name of the Project. Enter using single-byte alphanumeric characters and available symbols (_-). [Maximum length] 40 bytes',NULL,'0',_____DATE_____,1);
